import sys
from collections import Counter

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    words = data[1:1 + n]
    letters = data[1 + n]
    avail = Counter(letters)
    m = len(letters)
    best = None
    for w in words:
        lw = len(w)
        if lw > m:
            continue
        if best is not None:
            if lw < len(best):
                continue
            if lw == len(best) and w >= best:
                continue
        ok = True
        for ch, k in Counter(w).items():
            if avail[ch] < k:
                ok = False
                break
        if ok:
            best = w
    print(best if best is not None else -1)

main()

